/** 
 * Joins this chat room with the specified nickname so that the user would start receiving events and messages for it. If the chat room already contains a user with this nickname, the method would throw an OperationFailedException with code IDENTIFICATION_CONFLICT.
 * @param nickname the nickname to use.
 * @throws OperationFailedException with the corresponding code if an error occurs while joining the room.
 */
public void joinAs(final String nickname) throws OperationFailedException {
  try {
    this.setUserNickname(nickname);
    this.join();
  } catch (IllegalArgumentException e) {
    throw new OperationFailedException("Invalid nickname provided", OperationFailedException.IDENTIFICATION_CONFLICT, e);
  } catch (IllegalStateException e) {
    throw new OperationFailedException("Cannot join room in current state", OperationFailedException.INTERNAL_ERROR, e);
  }
}
